    * Helper to respond to the next outgoing request
    */
   function respondToNext(result: unknown) {
     return new Promise<void>((resolve) => {
       stdout.once('data', (chunk: Buffer) => {
         const request = JSON.parse(chunk.toString());
         stdin.write(
           JSON.stringify({
             jsonrpc: '2.0',
             id: request.id,
             result,
           }) + '\n',
         );
         resolve();
       });
