301	  /**
302	   * Process a complete line of input
303	   */
304	  private processLine(line: string): void {
305	    try {
306	      const message = JSON.parse(line);
307	      this.handleMessage(message);
308	    } catch {
309	      // Malformed JSON - send parse error response
310	      this.sendError(null, {
311	        code: -32700,
312	        message: "Parse error",
313	        data: { line },
314	      });
315	    }
316	  }
317	
318	  /**
319	   * Handle a parsed JSON-RPC message
320	   */
321	  private handleMessage(message: unknown): void {
322	    if (isResponse(message)) {
323	      this.handleResponse(message);
324	    } else if (isError(message)) {
325	      this.handleErrorResponse(message);
326	    } else if (isRequest(message)) {
327	      // Agent is sending us a request (e.g., tool call) - this proves it's alive
328	      // Reset timeout timers for any pending requests
329	      this.resetPendingTimers();
330	      this.emit("request", message);
331	    } else if (isNotification(message)) {
332	      // Agent is sending us a notification - also proves it's alive
333	      this.resetPendingTimers();
334	      this.emit("notification", message);
335	    } else {
336	      // Invalid message
337	      this.sendError(null, {
338	        code: -32600,
339	        message: "Invalid Request",
340	        data: message,
341	      });
342	    }
343	  }
344	
345	  /**
346	   * Handle a JSON-RPC response
347	   */
348	  private handleResponse(response: JsonRpcResponse): void {
349	    const pending = this.pending.get(response.id);
350	    if (pending) {
351	      clearTimeout(pending.timer);
352	      this.pending.delete(response.id);
353	      pending.resolve(response.result);
354	    } else {
355	      // Unexpected response
356	      console.error(
357	        `Warning: Received response for unknown request ID: ${response.id}`,
358	      );
359	    }
360	  }
361	
362	  /**
363	   * Handle a JSON-RPC error response
364	   */
365	  private handleErrorResponse(error: JsonRpcError): void {
366	    // JSON-RPC error code for "Method not found"
367	    const METHOD_NOT_FOUND = -32601;
368	
369	    if (error.id === null) {
370	      // Error without request ID - emit as event
371	      this.emit("error", error.error);
372	      return;
373	    }
374	
375	    const pending = this.pending.get(error.id);
376	    if (pending) {
377	      clearTimeout(pending.timer);
378	      this.pending.delete(error.id);
379	
380	      // Skip logging for expected "Method not found" errors on optional methods
381	      const isSilentMethodNotFound =
382	        pending.options?.silentMethodNotFound &&
383	        error.error.code === METHOD_NOT_FOUND;
384	
385	      if (!isSilentMethodNotFound) {
386	        console.error(
387	          `JSON-RPC error: ${error.error.message} (code: ${error.error.code}, method: ${pending.method})`,
388	        );
389	      }
390	
391	      const err = Object.assign(new Error(error.error.message), {
392	        code: error.error.code,
393	        data: error.error.data,
394	      });
395	      pending.reject(err);
396	    } else {
397	      // Unexpected error response
398	      console.error(
399	        `Warning: Received error for unknown request ID: ${error.id}`,
400	      );
401	    }
402	  }
403	
404	  /**
405	   * Handle stdin end
406	   */
407	  private handleEnd(): void {
408	    this.close();
409	  }
410	
411	  /**
412	   * Handle stdin error
413	   */
414	  private handleError(err: Error): void {
415	    console.error(`Stdin error: ${err.message}`);
416	    this.emit("error", err);
417	    this.close();
418	  }
419	
420	  /**
421	   * Handle stdout write/pipe errors.
422	   *
423	   * EPIPE (or destroyed stream) means the peer is gone. Treat this as a
424	   * closed connection instead of surfacing an uncaught exception.
425	   */
426	  private handleOutputError(err: unknown): void {
427	    const error = err instanceof Error ? err : new Error(String(err));
428	    const code = (error as NodeJS.ErrnoException).code;
429	
430	    if (code === "EPIPE" || code === "ERR_STREAM_DESTROYED") {
431	      this.close();
432	      return;
433	    }
434	
435	    console.error(`Stdout error: ${error.message}`);
436	    this.emit("error", error);
437	    this.close();
438	  }
